"""Render the 1280×640 social card (docs/assets/social-preview.png) from tokens and local fonts.

uv run python scripts/social.py      # needs Google Chrome for the PNG
"""

from __future__ import annotations

import shutil
import subprocess
from pathlib import Path

from precedent.theme import DARK as P

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "docs" / "assets" / "src" / "social-preview.html"
PNG = ROOT / "docs" / "assets" / "social-preview.png"
CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"

HTML = f"""<!doctype html>
<!-- Generated by scripts/social.py. Fonts: SIL OFL, docs/assets/fonts. -->
<html><head><meta charset="utf-8"><style>
@font-face{{font-family:'Instrument Serif';src:url('../fonts/InstrumentSerif-Regular.ttf')}}
@font-face{{font-family:Geist;src:url('../fonts/Geist.ttf');font-weight:100 900}}
@font-face{{font-family:'Geist Mono';src:url('../fonts/GeistMono.ttf');font-weight:100 900}}
*{{box-sizing:border-box;margin:0}}
body{{width:1280px;height:640px;background:{P.bg};color:{P.ink};font-family:Geist,sans-serif;
  display:grid;grid-template-columns:1fr 540px;gap:56px;padding:76px 72px 64px;overflow:hidden;position:relative}}
.brand{{display:flex;align-items:center;gap:22px}}
.mark{{display:flex;flex-direction:column;gap:8px}}
.mark i{{display:block;width:62px;height:26px;border-radius:8px;border:2.5px solid}}
.mark i:first-child{{border-color:{P.red};background:{P.red_bg}}}
.mark i:last-child{{border-color:{P.green};background:{P.green_bg}}}
h1{{font:400 104px/0.9 'Instrument Serif',serif;letter-spacing:-2px}}
h2{{font:500 44px/1.15 Geist,sans-serif;letter-spacing:-0.8px;margin-top:46px}}
p{{color:{P.muted};font-size:24px;line-height:1.45;margin-top:22px;max-width:580px}}
.tags{{position:absolute;left:72px;bottom:58px;font:400 18px 'Geist Mono',monospace;color:{P.faint}}}
.card{{align-self:center;background:{P.panel};border:1px solid {P.line};border-radius:20px;padding:30px 34px;
  font:400 19px/1.7 'Geist Mono',monospace}}
.k{{color:{P.accent}}} .m{{color:{P.muted}}} .f{{color:{P.faint}}}
.del{{background:{P.red_bg};color:{P.red};margin:0 -34px;padding:0 34px}}
.add{{background:{P.green_bg};color:{P.green};margin:0 -34px;padding:0 34px}}
.gate{{margin-top:22px;padding-top:20px;border-top:1px solid {P.line};display:grid;grid-template-columns:auto 1fr;gap:10px 16px;font-size:17px}}
.b{{font-weight:700;border-radius:999px;padding:1px 14px;border:1px solid;justify-self:start}}
.x{{color:{P.red};background:{P.red_bg}}} .ok{{color:{P.green};background:{P.green_bg}}}
</style></head><body>
<div>
  <div class="brand"><div class="mark"><i></i><i></i></div><h1>precedent</h1></div>
  <h2>Pull requests for<br>AI judgment</h2>
  <p>A human correction to an LLM judge becomes a scoped rule: tested on every case, approved by a second person, reversible.</p>
  <div class="tags">gate · four-eyes · hash-chained log · runs offline</div>
</div>
<div class="card">
  <div><span class="k">item</span>: escalation_offered</div>
  <div><span class="k">when</span>:</div>
  <div class="del">-  mentions_repayment</div>
  <div class="add">+  supervisor_callback_offered</div>
  <div><span class="k">then</span>: pass</div>
  <div><span class="k">counter_examples</span>: <span class="m">[CASE-005, …]</span></div>
  <div class="gate">
    <span class="b x">✗ BLOCKED</span><span class="f">v1 · fixes 2 · breaks 3</span>
    <span class="b ok">✓ PASSED</span><span class="f">v2 · fixes 3 · breaks 0</span>
  </div>
</div>
</body></html>
"""


def main() -> int:
    SRC.write_text(HTML, encoding="utf-8")
    if shutil.which(CHROME) or Path(CHROME).exists():
        subprocess.run(
            [CHROME, "--headless=new", "--disable-gpu", "--hide-scrollbars", "--allow-file-access-from-files",
             "--window-size=1280,640", "--virtual-time-budget=3000", f"--screenshot={PNG}", SRC.as_uri()],
            check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )  # fmt: skip
        print(f"{PNG.relative_to(ROOT)} {PNG.stat().st_size // 1024} KB")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
